#include <ranges>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    int values[]{1, 2, 3};
    int factor = 2;
    auto transform =
        std::views::transform(values, [factor](int n) { return n * factor; });
    auto copy = transform;
    assert(*copy.begin() == 2);
    auto filter = std::views::filter(values, [](int n) { return n > 1; });
    assert(*filter.begin() == 2);
    auto copied = filter;
    assert(*copied.begin() == 2);
}
